<?php
declare(strict_types=1);
require_once __DIR__ . '/_seller.php';
$pdo = market_boot(); $user = market_require_user($pdo); seller_access_or_message($pdo, $user);
$ctx = seller_query_context($pdo, $user, true); seller_header('Buyer Messages', 'messages', $user, $ctx['seller']);
if ($ctx['message']): ?><div class="alert ok"><?= e($ctx['message']) ?></div><?php endif; if ($ctx['error']): ?><div class="alert err"><?= e($ctx['error']) ?></div><?php endif; ?>
<section class="sc-grid"><?php foreach ($ctx['inquiries'] as $row): ?><form method="post" class="sc-card sc-panel span-6 sc-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reply_inquiry"><input type="hidden" name="inquiry_id" value="<?= (int) $row['id'] ?>"><div class="sc-panel-head"><h2><?= e((string) $row['buyer_name']) ?></h2><span class="badge good"><?= e((string) $row['status']) ?></span></div><p><strong><?= e((string) $row['listing_title']) ?></strong><br><span class="muted"><?= e((string) $row['message']) ?></span></p><div class="sc-form-grid"><select name="status"><?php foreach (['responded','quoted','accepted','closed','cancelled'] as $status): ?><option value="<?= e($status) ?>" <?= (string) $row['status'] === $status ? 'selected' : '' ?>><?= e(marketplace_status_label($status)) ?></option><?php endforeach; ?></select><input type="number" step="0.01" name="quoted_amount" value="<?= e((string) ($row['quoted_amount'] ?? '')) ?>" placeholder="Quoted amount"></div><textarea name="seller_reply" placeholder="Reply to buyer"><?= e((string) ($row['seller_reply'] ?? '')) ?></textarea><div class="sc-actions"><button class="sc-btn" type="submit">Save Reply</button></div></form><form method="post" class="span-6" style="margin-top:-12px"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_order"><input type="hidden" name="inquiry_id" value="<?= (int) $row['id'] ?>"><button class="sc-btn secondary" type="submit">Create Order From Request</button></form><?php endforeach; ?><?php if (!$ctx['inquiries']): ?><div class="empty span-12">No buyer message yet.</div><?php endif; ?></section>
<?php seller_footer(); ?>
